import re

FOLDER = re.compile(r"^Folder:\s+(?P<folder>\S.*?)\s*$")
FIELD = re.compile(r"^(?P<key>\S.*?):(?:\s{2,}(?P<value>\S.*?)?)?\s*$")
LOOSE = re.compile(r"^(?P<key>\S.*?):\s+(?P<value>\S.*?)\s*$")
VALUE_COL = 38      # schtasks /FO LIST pads every key to this column


def field(ln):
    # keys may hold colons (Repeat: Until: Time:), so trust the fixed column first
    head, tail = ln[:VALUE_COL], ln[VALUE_COL:]
    if len(ln) > VALUE_COL and head.endswith(" ") and head.rstrip().endswith(":") and tail[:1] != " ":
        return head.rstrip()[:-1], tail.strip()
    m = FIELD.match(ln) or LOOSE.match(ln)
    if m:
        return m.group("key"), m.group("value") or ""
    return None, None


def parse(lines):
    tasks, cols, used = [], ["Folder"], []
    folder, cur = "", None
    for j, ln in enumerate(lines):
        if not ln.strip():
            cur = None
            continue
        m = FOLDER.match(ln)
        if m:
            folder = m.group("folder")
            cur = None
            used.append(j)
            continue
        key, value = field(ln)
        if key is None:
            continue
        # the block repeats once per task; a key seen again starts the next one
        if cur is None or key in cur:
            cur = {"Folder": folder}
            tasks.append(cur)
        cur[key] = value
        if key not in cols:
            cols.append(key)
        used.append(j)
    tasks = [{k: t.get(k, "") for k in cols} for t in tasks]
    return [{"name": "tasks", "kind": "table", "lines": used, "records": tasks}]
